### `src/CheckoutPage.tsx`

```tsx
import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';
import { CartItem, DeliveryAddress, DeliveryAddressErrors } from './types';

interface CheckoutPageProps {
  cartItems: CartItem[];
  shippingCost?: number;
  currencySymbol?: string;
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  addressLine1: '',
  addressLine2: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

const COUNTRIES = [
  'United States',
  'United Kingdom',
  'Germany',
  'France',
  'Spain',
  'Italy',
  'Netherlands',
  'Canada',
  'Australia',
];

function formatCurrency(amount: number, symbol: string): string {
  return `${symbol}${amount.toFixed(2)}`;
}

function validateAddress(address: DeliveryAddress): DeliveryAddressErrors {
  const errors: DeliveryAddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Full name is required.';
  }
  if (!address.addressLine1.trim()) {
    errors.addressLine1 = 'Address is required.';
  }
  if (!address.city.trim()) {
    errors.city = 'City is required.';
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required.';
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code.';
  }
  if (!address.country.trim()) {
    errors.country = 'Country is required.';
  }
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required.';
  } else if (!/^[0-9+()\s-]{7,20}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number.';
  }

  return errors;
}

const CheckoutPage: React.FC<CheckoutPageProps> = ({
  cartItems,
  shippingCost = 4.99,
  currencySymbol = '$',
  onBackToCart,
  onPay,
}) => {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<DeliveryAddressErrors>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [cartItems]
  );

  const total = cartItems.length > 0 ? subtotal + shippingCost : 0;

  function handleFieldChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handlePaySubmit(e: React.FormEvent) {
    e.preventDefault();
    setPayError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) {
      return;
    }
    if (cartItems.length === 0) {
      setPayError('Your cart is empty.');
      return;
    }

    setIsPaying(true);
    try {
      await onPay(address);
    } catch {
      setPayError('Payment failed. Please try again.');
    } finally {
      setIsPaying(false);
    }
  }

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          disabled={isPaying}
        >
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="cart-summary" aria-label="Order summary">
          <h2>Your order</h2>

          {cartItems.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-image-placeholder" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatCurrency(item.unitPrice * item.quantity, currencySymbol)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="cart-totals">
            <div className="cart-totals-row">
              <span>Subtotal</span>
              <span>{formatCurrency(subtotal, currencySymbol)}</span>
            </div>
            <div className="cart-totals-row">
              <span>Shipping</span>
              <span>{formatCurrency(cartItems.length ? shippingCost : 0, currencySymbol)}</span>
            </div>
            <div className="cart-totals-row cart-totals-total">
              <span>Total</span>
              <span>{formatCurrency(total, currencySymbol)}</span>
            </div>
          </div>
        </section>

        <section className="address-section" aria-label="Delivery address">
          <h2>Delivery address</h2>
          <form className="address-form" onSubmit={handlePaySubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleFieldChange('fullName', e.target.value)}
                aria-invalid={!!errors.fullName}
              />
              {errors.fullName && <span className="field-error">{errors.fullName}</span>}
            </div>

            <div className="form-field">
              <label htmlFor="addressLine1">Address line 1</label>
              <input
                id="addressLine1"
                type="text"
                value={address.addressLine1}
                onChange={(e) => handleFieldChange('addressLine1', e.target.value)}
                aria-invalid={!!errors.addressLine1}
              />
              {errors.addressLine1 && (
                <span className="field-error">{errors.addressLine1}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="addressLine2">Address line 2 (optional)</label>
              <input
                id="addressLine2"
                type="text"
                value={address.addressLine2}
                onChange={(e) => handleFieldChange('addressLine2', e.target.value)}
              />
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={(e) => handleFieldChange('city', e.target.value)}
                  aria-invalid={!!errors.city}
                />
                {errors.city && <span className="field-error">{errors.city}</span>}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={(e) => handleFieldChange('postalCode', e.target.value)}
                  aria-invalid={!!errors.postalCode}
                />
                {errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="country">Country</label>
                <select
                  id="country"
                  value={address.country}
                  onChange={(e) => handleFieldChange('country', e.target.value)}
                  aria-invalid={!!errors.country}
                >
                  <option value="">Select a country</option>
                  {COUNTRIES.map((country) => (
                    <option key={country} value={country}>
                      {country}
                    </option>
                  ))}
                </select>
                {errors.country && <span className="field-error">{errors.country}</span>}
              </div>

              <div className="form-field">
                <label htmlFor="phone">Phone number</label>
                <input
                  id="phone"
                  type="tel"
                  value={address.phone}
                  onChange={(e) => handleFieldChange('phone', e.target.value)}
                  aria-invalid={!!errors.phone}
                />
                {errors.phone && <span className="field-error">{errors.phone}</span>}
              </div>
            </div>

            {payError && <p className="pay-error">{payError}</p>}

            <button
              type="submit"
              className="pay-button"
              disabled={isPaying || cartItems.length === 0}
            >
              {isPaying ? 'Processing…' : `Pay ${formatCurrency(total, currencySymbol)}`}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
};

export default CheckoutPage;
```

